package net.officefloor.hq.app.settings;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadSettings {
    public void load(@PathVariable("sheetId") String sheetId, ServerHttpConnection connection,
            SettingsRepository repository, Out<Settings> settings) throws BadRequestException {
        CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        settings.set(repository.load(id));
    }
}
package net.officefloor.hq.app.settings;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithSettings {
    public void respond(@Val Settings settings, ObjectResponse<Settings> response) {
        response.send(settings);
    }
}
package net.officefloor.hq.app.settings;

/** The role a user name holds on a sheet: clerk or steward. */
public record Role(String user, String role) {
}
package net.officefloor.hq.app.settings;

public record RoleRequest(String user, String role) {
}
package net.officefloor.hq.app.settings;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class SaveRole {
    public void save(@PathVariable("sheetId") String sheetId, @Val Role role, ServerHttpConnection connection,
            SettingsRepository repository, Audit audit, Out<Settings> settings) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!repository.sheetExists(id)) {
            throw new BadRequestException("no such sheet");
        }
        repository.setRole(id, role.user(), role.role());
        audit.record("ROLE_SET sheet=" + id + " by=" + by + " user=" + role.user() + " role=" + role.role());
        settings.set(repository.load(id));
    }
}
package net.officefloor.hq.app.settings;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class SaveSettings {
    public void save(@PathVariable("sheetId") String sheetId, @Val SettingsInput input,
            ServerHttpConnection connection, SettingsRepository repository, Audit audit, Rollup rollup,
            Out<Settings> settings) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        if (!repository.sheetExists(id)) {
            throw new BadRequestException("no such sheet");
        }
        Rollup.Snapshot before = rollup.take(id);
        if (input.setsClerkLimit()) {
            repository.setClerkLimit(id, input.clerkLimit());
            audit.record("SETTING_CHANGED sheet=" + id + " by=" + by + " key=clerk-limit value="
                    + (input.clerkLimit() == null ? "" : SettingsRepository.money(input.clerkLimit())));
        }
        if (input.setsFloor()) {
            repository.setFloor(id, input.floor());
            audit.record("SETTING_CHANGED sheet=" + id + " by=" + by + " key=floor value="
                    + SettingsRepository.money(input.floor()));
        }
        if (input.setsTerms()) {
            repository.setTerms(id, input.terms());
            audit.record("SETTING_CHANGED sheet=" + id + " by=" + by + " key=terms value=" + input.terms());
        }
        if (input.setsLatePct()) {
            repository.setLatePct(id, input.latePct());
            audit.record("SETTING_CHANGED sheet=" + id + " by=" + by + " key=late-pct value="
                    + SettingsRepository.money(input.latePct()));
        }
        rollup.record(id, by, before);
        settings.set(repository.load(id));
    }
}
package net.officefloor.hq.app.settings;

import java.math.BigDecimal;

/** A validated settings form: which settings it saves, the clerk limit scaled to two decimals (null for
 *  no limit), the floor scaled to two decimals the terms in days and the late percent scaled to two decimals. */
public record SettingsInput(boolean setsClerkLimit, BigDecimal clerkLimit, boolean setsFloor, BigDecimal floor, boolean setsTerms,
        Integer terms, boolean setsLatePct, BigDecimal latePct) {
}
package net.officefloor.hq.app.settings;

import java.util.List;

/** A sheet's settings: its clerk limit (two decimals; null means no limit), its floor (two decimals:
 *  the least a live due can be), its terms (the days after a claim's date that it is due by), its late percent (two decimals: what an
 *  overdue claim's due gains, of its figure, for every full 30 days it is overdue) and the roles set on it, by user name. A name not listed is a clerk. */
public record Settings(String clerkLimit, String floor, int terms, String latePct, List<Role> roles) {
}
package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class SettingsRepository {
    public static final String CLERK = "clerk";
    public static final String STEWARD = "steward";

    private final JdbcTemplate jdbc;

    public SettingsRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public boolean sheetExists(String sheetId) {
        Integer known = jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ?", Integer.class, sheetId);
        return known != null && known > 0;
    }

    /** The sheet's settings and roles, roles by user name. */
    public Settings load(String sheetId) {
        List<Role> roles = jdbc.query("SELECT user_name, role FROM sheet_role WHERE sheet_id = ? ORDER BY user_name",
                (rs, i) -> new Role(rs.getString("user_name"), rs.getString("role")), sheetId);
        BigDecimal limit = clerkLimit(sheetId);
        return new Settings(limit == null ? null : money(limit), money(floor(sheetId)), terms(sheetId),
                money(latePct(sheetId)), roles);
    }

    /** The sheet's clerk limit; null when it has none. */
    public BigDecimal clerkLimit(String sheetId) {
        List<BigDecimal> found = jdbc.query("SELECT clerk_limit FROM sheet WHERE id = ?",
                (rs, i) -> rs.getBigDecimal("clerk_limit"), sheetId);
        return found.isEmpty() ? null : found.get(0);
    }

    public void setClerkLimit(String sheetId, BigDecimal limit) {
        jdbc.update("UPDATE sheet SET clerk_limit = ? WHERE id = ?", limit, sheetId);
    }

    /** The sheet's floor: the least a live due can be; 1.00 unless set otherwise. */
    public BigDecimal floor(String sheetId) {
        List<BigDecimal> found = jdbc.query("SELECT floor FROM sheet WHERE id = ?",
                (rs, i) -> rs.getBigDecimal("floor"), sheetId);
        return found.isEmpty() || found.get(0) == null ? BigDecimal.ONE : found.get(0);
    }

    public void setFloor(String sheetId, BigDecimal floor) {
        jdbc.update("UPDATE sheet SET floor = ? WHERE id = ?", floor, sheetId);
    }

    /** The sheet's terms: the days after a claim's date that it is due by; 14 unless set otherwise. */
    public int terms(String sheetId) {
        List<Integer> found = jdbc.query("SELECT terms FROM sheet WHERE id = ?",
                (rs, i) -> rs.getInt("terms"), sheetId);
        return found.isEmpty() ? 14 : found.get(0);
    }

    public void setTerms(String sheetId, int terms) {
        jdbc.update("UPDATE sheet SET terms = ? WHERE id = ?", terms, sheetId);
    }

    /** The sheet's late percent: what an overdue claim's due gains, of its figure, for every full 30 days
     *  it is overdue; 0.00 unless set otherwise. */
    public BigDecimal latePct(String sheetId) {
        List<BigDecimal> found = jdbc.query("SELECT late_pct FROM sheet WHERE id = ?",
                (rs, i) -> rs.getBigDecimal("late_pct"), sheetId);
        return found.isEmpty() || found.get(0) == null ? BigDecimal.ZERO : found.get(0);
    }

    public void setLatePct(String sheetId, BigDecimal pct) {
        jdbc.update("UPDATE sheet SET late_pct = ? WHERE id = ?", pct, sheetId);
    }

    /** The role a user name holds on the sheet: clerk unless set otherwise. */
    public String role(String sheetId, String user) {
        List<String> found = jdbc.query("SELECT role FROM sheet_role WHERE sheet_id = ? AND user_name = ?",
                (rs, i) -> rs.getString("role"), sheetId, user);
        return found.isEmpty() ? CLERK : found.get(0);
    }

    public void setRole(String sheetId, String user, String role) {
